import java.util.Scanner;

public class Main {
    public static int computeGCD(int a, int b) {
        int gcdValue = Math.max(a, b);
        while (true) {
            if (a % gcdValue == 0 && b % gcdValue == 0)
                break;
            gcdValue--;
        }
        return gcdValue;
    }

    public static void calculateDifference(double x, double y, double a, double b, double[] result) {
        result[0] = Math.abs(x * b - y * a);
        result[1] = y * b;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        if (n > y) {
            int g = computeGCD((int) x, (int) y);
            if (g != 1) {
                x /= g;
                y /= g;
            }
            System.out.println((x) + "/" + (y));
            sc.close();
            return;
        }

        double minRatio = 1e9;
        int bestA = 0, bestB = 0;

        for (double b = n; b >= 1; b--) {
            double a = (x * b) / y;
            if (Math.floor(a) == a) {
                bestA = (int) a;
                bestB = (int) b;
                break;
            } else {
                double[] tempResult = new double[2];
                calculateDifference(x, y, Math.floor(a), b, tempResult);
                double tempNum = tempResult[0];
                double tempDen = tempResult[1];
                double tempRatio = tempNum / tempDen;

                if (tempRatio < minRatio) {
                    minRatio = tempRatio;
                    bestA = (int) Math.floor(a);
                    bestB = (int) b;
                } else if (tempRatio == minRatio && (int) Math.floor(a) < bestA) {
                    bestA = (int) Math.floor(a);
                    bestB = (int) b;
                }

                calculateDifference(x, y, Math.ceil(a), b, tempResult);
                tempNum = tempResult[0];
                tempDen = tempResult[1];
                tempRatio = tempNum / tempDen;

                if (tempRatio < minRatio) {
                    minRatio = tempRatio;
                    bestA = (int) Math.ceil(a);
                    bestB = (int) b;
                } else if (tempRatio == minRatio && (int) Math.ceil(a) < bestA) {
                    bestA = (int) Math.ceil(a);
                    bestB = (int) b;
                }
            }
        }

        int g = computeGCD(bestA, bestB);
        if (g != 1) {
            bestA /= g;
            bestB /= g;
        }
        System.out.println(bestA + "/" + bestB);
        sc.close();
    }
}
